import{M as e,O as t,d as n,h as r,p as i}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as a}from"./app-fxBgVz1h.js";var o=JSON.parse(`{"path":"/AI%E7%9F%A5%E8%AF%86%E5%BA%93/rag/rag-knowledge-update.html","title":"RAG 知识库文档如何更新：增量更新、版本控制、去重与全量重建","lang":"zh-CN","frontmatter":{"title":"RAG 知识库文档如何更新：增量更新、版本控制、去重与全量重建","description":"深入解析 RAG 知识库更新的核心目标与工程实践，涵盖 Embedding 模型一致性、元数据设计、同步机制、增量更新与全量重建对比、生产级灰度发布与回滚方案，以及常见踩坑点。","category":"AI 应用开发","head":[["meta",{"name":"keywords","content":"RAG知识库更新,增量索引,全量重建,版本控制,向量数据库更新,Embedding模型一致性,去重,幂等更新"}]]},"git":{"createdTime":1787385570000,"updatedTime":1787385570000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":26.42,"words":7927},"filePathRelative":"AI知识库/rag/rag-knowledge-update.md"}`),s={name:`rag-knowledge-update.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<blockquote><p>本文转载自 <a href="https://javaguide.cn/ai/" target="_blank" rel="noopener noreferrer">JavaGuide《AI 应用开发》专栏</a>(作者:Snailclimb),原文:<a href="https://javaguide.cn/ai/rag/rag-knowledge-update.html" target="_blank" rel="noopener noreferrer">https://javaguide.cn/ai/rag/rag-knowledge-update.html</a>。著作权归原作者所有,本站按作者转载要求注明出处,仅供个人学习使用。</p></blockquote><p>第一个企业知识库 RAG 系统上线后，很多团队都会碰到一个很真实的问题：文档明明更新了，回答还是老样子。</p><p>这时候先别急着怪 LLM。更常见的原因是知识库没有同步更新，或者更新链路只做了“写入新内容”，没有处理旧版本、权限、索引一致性这些细节。</p><p>文档变更频繁之后，问题会更明显：每次都全量重建索引，成本和耗时扛不住；只更新变化部分，又怕漏掉旧块；只插入新向量，不清理旧版本，过期内容还会继续被召回；换了 Embedding 模型，历史数据到底要不要全部重索引，也绕不开。</p><p>知识库更新要同时处理版本、权限和多个索引之间的一致性。本文沿着新增、修改、删除三类事件，说明增量同步、全量重建、灰度、回滚和监控怎么配合。</p><h2 id="知识库更新要解决哪些问题" tabindex="-1"><a class="header-anchor" href="#知识库更新要解决哪些问题"><span>知识库更新要解决哪些问题？</span></a></h2><p>在讲具体方案之前，先把目标说清楚。</p><p>更新完成后，检索结果要与当前文档一致，不能越权；同步失败时还要能定位到具体文档和写入端，并能恢复到上一版索引。</p><p>动态性指的是，文档变了，索引要能跟上。这个“及时”不一定都是秒级，可能是分钟级，也可能是天级，取决于业务对实时性的要求。内部制度库也许一天同步一次就够，客服知识库和合规条款就可能需要更快。</p><p>准确性指的是，更新后召回的内容要和当前文档一致，不能文档已经改了，模型还在引用旧版本。这个问题一旦发生，用户感知会很明显。</p><p>一致性更麻烦。同一个文档有不同版本，向量库、元数据库、全文检索又是不同系统，任何一端漏写或延迟，都可能导致结果不一致。</p><p>可回滚是为了出故障时能快速切回上一个健康状态，而不是靠人工临时修数据。可观测则要求更新过程能监控，更新结果能评估，失败原因能追到具体环节。</p><p>这些目标看起来像常识，但很多项目只做了第一步“更新”，后面几步全靠运气。结果就是文档改了十版，回答还停在第一版；删了一篇敏感文档，过了几个月还能被召回出来。</p><h2 id="为什么-embedding-模型必须保持一致" tabindex="-1"><a class="header-anchor" href="#为什么-embedding-模型必须保持一致"><span>为什么 Embedding 模型必须保持一致？</span></a></h2><p>这一点要单独拎出来讲：索引时用的 Embedding 模型，必须和查询时用的模型一致。</p><p>Embedding 模型会把文本转成向量，不同模型的向量空间并不通用。同一句话用 OpenAI 的 <code>text-embedding-3-small</code> 编码，和用 sentence-transformers 的 <code>all-MiniLM-L6-v2</code> 编码，得到的向量没有可比性。如果索引用模型 A，查询用模型 B，就等于在两个不同空间里算相似度。</p><p>具体表现还要看向量维度。如果维度不同，通常无法放进同一个索引，很多向量库会直接拒绝插入或查询。如果维度相同但模型不同，相似度分数也不具备可比性，召回结果不能信。它不是简单的“随机”，而是整个排序基础已经坏了。</p><p>生产里最容易忽视的有两个场景。</p><p><strong>第一个是模型升级。</strong> 业务方觉得新模型效果更好，想从 <code>text-embedding-3-small</code> 切到 <code>text-embedding-3-large</code>。这意味着历史数据必须重新编码、重新入索引。工程上可以用双索引并行和灰度切流降低风险，但重建这一步绕不过去。</p><p><strong>第二个是本地模型和 API 模型混用。</strong> 测试环境用本地 sentence-transformers，生产环境用 OpenAI API。这种差异在团队协作里特别常见，测试看起来正常，上线后召回率直接腰斩。</p><p>比较稳的做法是把 Embedding 模型信息写进元数据，每次查询时都校验模型版本。不匹配时，要么拒绝查询，要么打警告日志并降级到更保守的召回策略。</p><table><thead><tr><th>字段</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>embedding_model</code></td><td>模型名称</td><td><code>text-embedding-3-large</code></td></tr><tr><td><code>embedding_model_version</code></td><td>模型版本</td><td><code>2025-01-15</code></td></tr><tr><td><code>embedding_dimension</code></td><td>向量维度</td><td><code>3072</code></td></tr></tbody></table><p>当 Embedding 模型需要升级时，建议按下面的流程走：</p><ol><li>在新索引中用新模型重建所有数据。</li><li>新旧索引并行运行一段时间，对比召回率和回答质量。</li><li>确认新索引稳定后，通过索引别名把流量切到新索引。</li><li>保留旧索引一段时间，用于快速回滚。</li><li>确认没有问题后，再删除旧索引。</li></ol><p>这个思路和数据库蓝绿部署很像：不要原地改，先建一套新的，验证通过后再切。</p><h2 id="如何设计支持更新的元数据体系" tabindex="-1"><a class="header-anchor" href="#如何设计支持更新的元数据体系"><span>如何设计支持更新的元数据体系？</span></a></h2><p>好的元数据设计，是增量更新和回滚的前提。很多 RAG 系统跑着跑着会“失忆”，不是因为不知道文档内容，而是不知道这条向量对应哪个文档、哪个版本、什么时候入库、权限是什么。</p><p>每个 Chunk 至少应该带上这些元数据：</p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-json"><span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;doc_id&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;doc-uuid-001&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;chunk_id&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;chunk-uuid-001&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;content_hash&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;sha256:abc123...&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;version_id&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;chunk_strategy&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;semantic&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;chunk_size&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">512</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;chunk_overlap&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;source_id&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;confluence-page-123&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;source_type&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;confluence&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;title&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;订单中心接口文档&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;section_path&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;技术文档 / 订单系统 / 接口规范&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;page&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;tenant_id&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;tenant-001&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;acl&quot;</span><span style="color:#ABB2BF;">: [</span><span style="color:#98C379;">&quot;role:admin&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;team:order-team&quot;</span><span style="color:#ABB2BF;">],</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;created_at&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;2025-03-01T10:00:00Z&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;updated_at&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;2025-04-15T14:30:00Z&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;embedding_model&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;text-embedding-3-large&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;embedding_model_version&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;2025-01-15&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;embedding_dimension&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">3072</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;is_deleted&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">false</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>切分策略也要版本化。切分方式、重叠率、解析方式一旦变化，影响不比 Embedding 模型小，也应该触发重建或双索引灰度。记录 <code>chunk_strategy</code>、<code>chunk_size</code>、<code>chunk_overlap</code> 这些字段，后面做评估和回滚才有依据。</p><p><code>content_hash</code> 是增量更新的核心。它不是文件哈希，而是文档正文或 Chunk 内容的哈希。常见算法有几种：MD5 速度快，但有碰撞风险，适合对碰撞不敏感的场景；SHA-256 碰撞风险极低，更推荐生产使用；SimHash 适合判断内容是否大致相同，常用于网页去重，但不能精确定位具体变化点。</p><p>生产环境里，<code>content_hash</code> 主要用来判断“这段文本有没有变”。入库时计算哈希，和数据库里已有记录对比。如果一致，说明内容没变，可以跳过 Embedding；如果不一致，就要重新编码。</p><p><code>version_id</code> 记录文档修改次数。每次文档更新，<code>version_id</code> 加一。它配合 <code>content_hash</code> 使用，可以追踪变更历史，也方便回滚。</p><p><code>is_deleted</code> 是软删除标记。只从向量库删除记录而不在元数据库保留删除状态，会让审计、恢复和跨索引同步失去依据。收到删除事件时，可以先把 <code>is_deleted</code> 设为 <code>true</code>；重新上传时创建新版本或恢复记录，并重新计算 <code>content_hash</code>；查询时默认只保留 <code>is_deleted = false</code> 的记录。</p><p>软删除不只是为了区分新旧文档，它还给审计、误删恢复、延迟物理删除、跨系统一致性留了缓冲窗口。</p><p><code>tenant_id</code> 和 <code>acl</code> 是多租户和权限控制的基础。所有会进入模型上下文的内容都必须先通过授权检查，通常在检索前或检索时按租户、角色、资源 ACL 过滤，避免无权限文档占用 Top-K 或泄露给模型。动态权限、跨组织继承等复杂规则可以在候选召回后再次校验，但二次校验必须发生在组装模型上下文之前；返回引用前还可以再核对一次，作为防御性检查。</p><h2 id="新增、修改、删除文档如何同步" tabindex="-1"><a class="header-anchor" href="#新增、修改、删除文档如何同步"><span>新增、修改、删除文档如何同步？</span></a></h2><p>文档从源系统到向量库，中间会经过多个环节。任何一环出问题，都会导致数据不一致。</p>`,38),r(d,{code:``}),o[1]||=i(`<p>这里要特别注意部分成功。向量库、元数据库、全文索引通常不在同一个事务域，一次写三端很可能出现部分成功。更稳的做法是以元数据库作为 source of truth，记录每个 Chunk 的索引状态，比如 <code>index_status = &#39;ready&#39; / &#39;partial_failed&#39;</code>。后台补偿任务定期重试失败端，再通过 reconciliation 扫描差异。</p><h3 id="新增文档" tabindex="-1"><a class="header-anchor" href="#新增文档"><span>新增文档</span></a></h3><p>新增是三类操作里最简单的。一般流程是：解析文档，提取正文、标题、层级结构；按既定策略切分 Chunk；计算每个 Chunk 的 <code>content_hash</code>；检查哈希是否已经存在；不存在时生成向量，并写入向量库、元数据库、全文索引。</p><p>幂等性很重要。新增操作必须能重复执行。即使消息队列重复投递同一条消息，或者 worker 崩溃重启后再次处理，也不应该产生重复记录。</p><h3 id="修改文档" tabindex="-1"><a class="header-anchor" href="#修改文档"><span>修改文档</span></a></h3><p>修改比新增复杂，关键问题是旧版本数据怎么办。</p><p>需要避免查询同时看到两版内容，也要避免更新过程中暂时查不到任何版本。常见做法是先写入不可见的新版本，再原子切换活动版本：</p><ol><li>根据 <code>doc_id</code> 查询元数据库，记录当前活动版本和旧 <code>chunk_id</code> 列表。</li><li>写入带新 <code>version_id</code> 的 Chunk、向量和全文索引，并保持 <code>status = &#39;building&#39;</code>，不参与在线检索。</li><li>校验三端写入结果后，在元数据库或索引别名中把活动版本原子切到新版。</li><li>将旧版标记为删除，按保留策略异步清理。</li></ol><p>如果向量库支持基于主键的原子更新，比如 Milvus 的 upsert，可以直接覆盖同一主键记录。但要注意，upsert 只能覆盖同一主键实体。如果文档重新切分后 Chunk 数量或 <code>chunk_id</code> 变化，仍然要按 <code>doc_id + version_id</code> 清理旧版本残留。</p><p>如果存储端不能原子替换整篇文档，就用 <code>active_version</code> 过滤、索引别名或双索引切换。直接先删旧记录再写新记录，会出现短暂的空窗；直接先写新记录但不做版本过滤，则可能同时命中新旧内容。</p><p>一个很常见的坑是只写新向量，不删旧向量。</p><p>如果文档修改 10 次后，向量库仍保留 10 个可检索版本，查询可能命中过时内容。修改流程必须停用旧版本，并按保留策略清理旧向量，否则知识库会持续失真。</p><h3 id="删除文档" tabindex="-1"><a class="header-anchor" href="#删除文档"><span>删除文档</span></a></h3><p>删除可以分为软删除和物理删除。</p><p>软删除是把 <code>is_deleted</code> 标记设为 <code>true</code>。它便于保留变更历史和处理误删，但不适用于要求立即擦除数据的合规请求。</p><p>物理删除是从向量库、元数据库、全文索引和相关缓存中移除记录。软删除保留多久，要根据业务恢复目标、数据分类和合规要求确定，不能把固定天数当作通用默认值。</p><p>软删除方便恢复和审计，但会增加存储成本和过滤开销。物理删除更彻底，适合合规删除、敏感数据删除，但恢复成本高。生产上更常见的是“软删除 + 延迟物理删除 + 删除审计日志”。如果是敏感文档，还要清理 rerank 缓存、LLM 上下文缓存等旁路缓存。</p><p>删除还有一个隐蔽问题：权限变更后的“幽灵数据”。比如一篇文档原本所有员工可见，后来改成“仅高管可见”。如果向量库里的旧 <code>acl</code> 没更新，普通员工查询时可能仍然召回这篇文档。正确做法是权限变更触发文档重新索引，确保元数据里的 <code>acl</code> 是最新的。如果向量库支持原子更新 ACL 字段，也可以不重建向量，只更新元数据。</p><h2 id="增量更新和全量重建各适合什么场景" tabindex="-1"><a class="header-anchor" href="#增量更新和全量重建各适合什么场景"><span>增量更新和全量重建各适合什么场景？</span></a></h2><p>常见组合是用增量更新处理日常变化，在模型升级、切分策略迁移或严重数据不一致时执行全量重建。是否定期全量重建，要看索引实现、更新频率和一致性检查结果。</p><table><thead><tr><th>维度</th><th>增量更新</th><th>全量重建</th></tr></thead><tbody><tr><td>触发条件</td><td>文档变更事件</td><td>定时任务或手动触发</td></tr><tr><td>覆盖范围</td><td>仅变化的文档</td><td>整个知识库</td></tr><tr><td>计算成本</td><td>低，只处理变化部分</td><td>高，需要处理全部数据</td></tr><tr><td>更新延迟</td><td>低，可近实时</td><td>高，可能需要数小时</td></tr><tr><td>数据一致性</td><td>依赖变更检测准确性</td><td>需基于源系统快照或版本时间戳保证与源系统一致</td></tr><tr><td>适用场景</td><td>日常变更、高频更新</td><td>模型升级、策略调整、故障恢复</td></tr><tr><td>主要风险</td><td>变更漏检导致数据陈旧</td><td>占用额外算力和存储；切换方案不完整时影响服务</td></tr></tbody></table><h3 id="增量更新适合什么场景" tabindex="-1"><a class="header-anchor" href="#增量更新适合什么场景"><span>增量更新适合什么场景？</span></a></h3><p>增量更新适合文档变更频率适中、对实时性有要求、知识库规模较大的场景。比如每天几十到几百次文档变更，业务能接受分钟级同步，全量重建成本又比较高。</p><p>增量更新依赖变更检测机制。常见方案有三种：</p><ol><li>Webhook / 事件驱动：源系统，比如 Confluence、Git、数据库，主动提供变更通知，RAG 系统订阅并处理。延迟最低，但要求源系统支持。</li><li>CDC（Change Data Capture）：监听数据库 binlog 或变更日志，捕获数据变化。适合结构化数据源。</li><li>定时轮询：按固定间隔，比如每 5 分钟扫描源系统，对比 <code>updated_at</code> 时间戳。实现简单，但有延迟，也会给源系统带来压力。</li></ol><p>生产里更稳的是事件驱动 + 轮询兜底。事件驱动处理日常增量，轮询用来防漏检。中间加消息队列，比如 Kafka、RocketMQ，用来解耦源系统和 RAG 处理流程。</p><h3 id="全量重建适合什么场景" tabindex="-1"><a class="header-anchor" href="#全量重建适合什么场景"><span>全量重建适合什么场景？</span></a></h3><p>全量重建通常用于这些情况：</p><ul><li>Embedding 模型升级。这是硬需求，绕不过去。</li><li>Chunk 策略调整。比如从固定 500 Token 改成语义切分。可以全量重建，也可以用版本化索引逐批迁移，但同一评测和检索链路要能区分策略版本。</li><li>数据结构变更。比如新增或修改元数据字段。</li><li>严重故障恢复。增量链路长期失灵，数据已经明显陈旧。</li><li>定期健康维护。部分向量库在高频删除后会留下 tombstone 删除标记、索引碎片，甚至出现召回退化。具体表现和索引类型、产品实现有关，比如基于 HNSW + tombstone 清理机制的产品，最好查对应向量库文档确认。</li></ul><p>全量重建最怕服务中断。比较稳的做法是索引别名切换：</p>`,30),r(d,{code:``}),o[2]||=i(`<p>步骤大致是：</p><ol><li>查询服务通过索引别名 <code>prod_index</code> 访问，旧索引是 <code>index_v1</code>。</li><li>后台启动重建任务，构建新索引 <code>index_v2</code>。</li><li>新索引验证通过后，把别名 <code>prod_index</code> 指向 <code>index_v2</code>。Milvus / Zilliz 的 alias 机制支持在 collection 间切换，其他向量库是否有同等能力要单独确认。</li><li>保留旧索引 <code>index_v1</code> 一段时间，比如 7 天，用于快速回滚。</li><li>确认没问题后，删除旧索引。</li></ol><h3 id="生产环境的稳态策略" tabindex="-1"><a class="header-anchor" href="#生产环境的稳态策略"><span>生产环境的稳态策略</span></a></h3><p>增量链路通过 Webhook 或 CDC 捕获日常变更，轮询和 reconciliation 用来发现漏写、漏删和乱序。全量重建按需触发：模型升级、索引策略迁移或一致性检查持续失败时再执行。部分系统会安排周期性重建，但周期要根据索引实现、删除比例、重建成本和一致性指标确定，不能统一按周或按月设置。</p><h2 id="如何让更新链路稳定可靠" tabindex="-1"><a class="header-anchor" href="#如何让更新链路稳定可靠"><span>如何让更新链路稳定可靠？</span></a></h2><h3 id="幂等更新-消息队列的好搭档" tabindex="-1"><a class="header-anchor" href="#幂等更新-消息队列的好搭档"><span>幂等更新：消息队列的好搭档</span></a></h3><p>消息队列天然会有重复投递。网络抖动、consumer 崩溃重启、offset 没提交，都可能导致同一条消息被重复消费。</p><p>幂等更新的重点是去重依据。比较可靠的是基于 <code>doc_id + content_hash</code> 或 <code>doc_id + version_id</code> 做唯一约束。但要注意，并发场景下，简单“先查再写”不够安全，两条相同或乱序消息同时到达时，仍然可能互相覆盖或重复写入。</p><p>更稳的做法有几种：</p><ol><li>依赖唯一约束：以 <code>doc_id + content_hash</code> 或 <code>doc_id + version_id</code> 建唯一索引，插入时让数据库拒绝重复。</li><li>乐观锁 / 分布式锁：写入新版本前先拿锁，防止并发覆盖。</li><li>事务 outbox：变更事件先写入 outbox 表，再由消费者幂等处理。</li></ol><p>下面的示例在唯一约束之外增加了索引状态。<code>index_status</code> 可以取 <code>pending</code>、<code>processing</code>、<code>partial_failed</code> 和 <code>ready</code>；<code>claim_token</code> 与 <code>claimed_at</code> 用于防止多个消费者同时处理同一条记录，并允许超时任务被接管。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> uuid </span><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> uuid4</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> process_document_change</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">event</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#ABB2BF;">    doc_id </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> event[</span><span style="color:#98C379;">&#39;doc_id&#39;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#ABB2BF;">    content </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> event[</span><span style="color:#98C379;">&#39;content&#39;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#ABB2BF;">    version_id </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> event.</span><span style="color:#61AFEF;">get</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;version_id&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    chunk_hash </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> compute_hash</span><span style="color:#ABB2BF;">(content)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 使用完整内容哈希，避免前缀相同的不同内容发生碰撞</span></span>
<span class="line"><span style="color:#ABB2BF;">    chunk_id </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> f</span><span style="color:#98C379;">&quot;</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">doc_id</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">_</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">version_id</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">_</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">chunk_hash</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 重复事件不会创建新记录；失败记录仍可从原状态继续处理</span></span>
<span class="line"><span style="color:#ABB2BF;">    db.</span><span style="color:#61AFEF;">execute</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;&quot;&quot;</span></span>
<span class="line"><span style="color:#98C379;">        INSERT INTO chunks (</span></span>
<span class="line"><span style="color:#98C379;">            doc_id, chunk_id, content_hash, version_id, is_deleted, index_status</span></span>
<span class="line"><span style="color:#98C379;">        )</span></span>
<span class="line"><span style="color:#98C379;">        VALUES (</span></span>
<span class="line"><span style="color:#98C379;">            :doc_id, :chunk_id, :content_hash, :version_id, false, &#39;pending&#39;</span></span>
<span class="line"><span style="color:#98C379;">        )</span></span>
<span class="line"><span style="color:#98C379;">        ON CONFLICT (doc_id, chunk_id) DO NOTHING</span></span>
<span class="line"><span style="color:#98C379;">    &quot;&quot;&quot;</span><span style="color:#ABB2BF;">, {</span></span>
<span class="line"><span style="color:#98C379;">        &#39;doc_id&#39;</span><span style="color:#ABB2BF;">: doc_id,</span></span>
<span class="line"><span style="color:#98C379;">        &#39;chunk_id&#39;</span><span style="color:#ABB2BF;">: chunk_id,</span></span>
<span class="line"><span style="color:#98C379;">        &#39;content_hash&#39;</span><span style="color:#ABB2BF;">: chunk_hash,</span></span>
<span class="line"><span style="color:#98C379;">        &#39;version_id&#39;</span><span style="color:#ABB2BF;">: version_id</span></span>
<span class="line"><span style="color:#ABB2BF;">    })</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">    claim_token </span><span style="color:#56B6C2;">=</span><span style="color:#56B6C2;"> str</span><span style="color:#ABB2BF;">(</span><span style="color:#61AFEF;">uuid4</span><span style="color:#ABB2BF;">())</span></span>
<span class="line"><span style="color:#ABB2BF;">    claimed </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> db.</span><span style="color:#61AFEF;">fetch_one</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;&quot;&quot;</span></span>
<span class="line"><span style="color:#98C379;">        UPDATE chunks</span></span>
<span class="line"><span style="color:#98C379;">        SET index_status = &#39;processing&#39;,</span></span>
<span class="line"><span style="color:#98C379;">            claim_token = :claim_token,</span></span>
<span class="line"><span style="color:#98C379;">            claimed_at = CURRENT_TIMESTAMP</span></span>
<span class="line"><span style="color:#98C379;">        WHERE doc_id = :doc_id</span></span>
<span class="line"><span style="color:#98C379;">          AND chunk_id = :chunk_id</span></span>
<span class="line"><span style="color:#98C379;">          AND (</span></span>
<span class="line"><span style="color:#98C379;">              index_status IN (&#39;pending&#39;, &#39;partial_failed&#39;)</span></span>
<span class="line"><span style="color:#98C379;">              OR (</span></span>
<span class="line"><span style="color:#98C379;">                  index_status = &#39;processing&#39;</span></span>
<span class="line"><span style="color:#98C379;">                  AND claimed_at &lt; CURRENT_TIMESTAMP - INTERVAL &#39;10 minutes&#39;</span></span>
<span class="line"><span style="color:#98C379;">              )</span></span>
<span class="line"><span style="color:#98C379;">          )</span></span>
<span class="line"><span style="color:#98C379;">        RETURNING chunk_id</span></span>
<span class="line"><span style="color:#98C379;">    &quot;&quot;&quot;</span><span style="color:#ABB2BF;">, {</span></span>
<span class="line"><span style="color:#98C379;">        &#39;doc_id&#39;</span><span style="color:#ABB2BF;">: doc_id,</span></span>
<span class="line"><span style="color:#98C379;">        &#39;chunk_id&#39;</span><span style="color:#ABB2BF;">: chunk_id,</span></span>
<span class="line"><span style="color:#98C379;">        &#39;claim_token&#39;</span><span style="color:#ABB2BF;">: claim_token</span></span>
<span class="line"><span style="color:#ABB2BF;">    })</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 没有抢到任务，说明记录已完成或仍由另一个消费者处理</span></span>
<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> claimed </span><span style="color:#C678DD;">is</span><span style="color:#D19A66;"> None</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">        logger.</span><span style="color:#61AFEF;">info</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Doc </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">doc_id</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> is ready or being processed, skipping&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">        return</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    try</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # upsert 必须以 chunk_id 为幂等键，重复执行不会产生多份向量</span></span>
<span class="line"><span style="color:#ABB2BF;">        embedding </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> embedding_model.</span><span style="color:#61AFEF;">encode</span><span style="color:#ABB2BF;">(content)</span></span>
<span class="line"><span style="color:#ABB2BF;">        vector_db.</span><span style="color:#61AFEF;">upsert</span><span style="color:#ABB2BF;">(doc_id, chunk_id, embedding, {</span></span>
<span class="line"><span style="color:#98C379;">            &#39;doc_id&#39;</span><span style="color:#ABB2BF;">: doc_id,</span></span>
<span class="line"><span style="color:#98C379;">            &#39;content_hash&#39;</span><span style="color:#ABB2BF;">: chunk_hash,</span></span>
<span class="line"><span style="color:#98C379;">            &#39;version_id&#39;</span><span style="color:#ABB2BF;">: version_id,</span></span>
<span class="line"><span style="color:#98C379;">            &#39;updated_at&#39;</span><span style="color:#ABB2BF;">: </span><span style="color:#61AFEF;">now</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">        })</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">        db.</span><span style="color:#61AFEF;">execute</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;&quot;&quot;</span></span>
<span class="line"><span style="color:#98C379;">            UPDATE chunks</span></span>
<span class="line"><span style="color:#98C379;">            SET index_status = &#39;ready&#39;,</span></span>
<span class="line"><span style="color:#98C379;">                claim_token = NULL,</span></span>
<span class="line"><span style="color:#98C379;">                claimed_at = NULL</span></span>
<span class="line"><span style="color:#98C379;">            WHERE doc_id = :doc_id</span></span>
<span class="line"><span style="color:#98C379;">              AND chunk_id = :chunk_id</span></span>
<span class="line"><span style="color:#98C379;">              AND claim_token = :claim_token</span></span>
<span class="line"><span style="color:#98C379;">        &quot;&quot;&quot;</span><span style="color:#ABB2BF;">, {</span></span>
<span class="line"><span style="color:#98C379;">            &#39;doc_id&#39;</span><span style="color:#ABB2BF;">: doc_id,</span></span>
<span class="line"><span style="color:#98C379;">            &#39;chunk_id&#39;</span><span style="color:#ABB2BF;">: chunk_id,</span></span>
<span class="line"><span style="color:#98C379;">            &#39;claim_token&#39;</span><span style="color:#ABB2BF;">: claim_token</span></span>
<span class="line"><span style="color:#ABB2BF;">        })</span></span>
<span class="line"><span style="color:#C678DD;">    except</span><span style="color:#ABB2BF;"> Exception </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> e:</span></span>
<span class="line"><span style="color:#ABB2BF;">        db.</span><span style="color:#61AFEF;">execute</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;&quot;&quot;</span></span>
<span class="line"><span style="color:#98C379;">            UPDATE chunks</span></span>
<span class="line"><span style="color:#98C379;">            SET index_status = &#39;partial_failed&#39;,</span></span>
<span class="line"><span style="color:#98C379;">                claim_token = NULL,</span></span>
<span class="line"><span style="color:#98C379;">                claimed_at = NULL</span></span>
<span class="line"><span style="color:#98C379;">            WHERE doc_id = :doc_id</span></span>
<span class="line"><span style="color:#98C379;">              AND chunk_id = :chunk_id</span></span>
<span class="line"><span style="color:#98C379;">              AND claim_token = :claim_token</span></span>
<span class="line"><span style="color:#98C379;">        &quot;&quot;&quot;</span><span style="color:#ABB2BF;">, {</span></span>
<span class="line"><span style="color:#98C379;">            &#39;doc_id&#39;</span><span style="color:#ABB2BF;">: doc_id,</span></span>
<span class="line"><span style="color:#98C379;">            &#39;chunk_id&#39;</span><span style="color:#ABB2BF;">: chunk_id,</span></span>
<span class="line"><span style="color:#98C379;">            &#39;claim_token&#39;</span><span style="color:#ABB2BF;">: claim_token</span></span>
<span class="line"><span style="color:#ABB2BF;">        })</span></span>
<span class="line"><span style="color:#ABB2BF;">        logger.</span><span style="color:#61AFEF;">error</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Failed to process </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">doc_id</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">e</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#C678DD;">        raise</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>唯一约束负责去重，条件更新负责原子抢占任务，<code>partial_failed</code> 则让后续重试可以继续写向量。这里使用 PostgreSQL 风格的 <code>RETURNING</code> 获取抢占结果，避免依赖不同数据库驱动行为不一致的 <code>rowcount</code>。如果业务数据库和向量数据库无法放进同一事务，向量写入必须按 <code>chunk_id</code> 幂等；即使向量已经写入、状态更新却失败，重试也可以安全地再次 <code>upsert</code>。生产环境还需要由定时任务扫描超过租约时间的 <code>processing</code> 记录。</p><h3 id="乱序事件处理" tabindex="-1"><a class="header-anchor" href="#乱序事件处理"><span>乱序事件处理</span></a></h3><p>消息队列的投递顺序不一定总是符合预期。RAG 更新链路里，先收到 v3 再收到 v2 很常见。如果不处理乱序，旧版本就可能覆盖新版本。</p><p>通常要做几件事：</p><ol><li>每个文档事件携带 <code>source_version</code>、<code>updated_at</code> 或单调递增的 <code>revision</code>，用于判断新旧。</li><li>写入前校验 <code>event.version &gt;= current_version</code>，旧事件直接丢弃或写入审计日志。</li><li>对同一 <code>doc_id</code> 做分区有序消费，比如 Kafka key 使用 <code>doc_id</code>，保证同一文档的消息落在同一 partition。</li><li>对乱序丢弃做监控打点，方便发现源系统事件异常。</li></ol><h3 id="失败重试和死信队列" tabindex="-1"><a class="header-anchor" href="#失败重试和死信队列"><span>失败重试和死信队列</span></a></h3><p>处理链路的任何环节都可能失败：网络抖动、API 限流、向量库暂时不可用、解析器异常，都会发生。</p><p>比较稳的策略是指数退避重试 + 死信队列兜底。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> process_with_retry</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">event</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">max_retries</span><span style="color:#ABB2BF;">=</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # max_retries 表示首次尝试失败后，最多再重试多少次</span></span>
<span class="line"><span style="color:#C678DD;">    for</span><span style="color:#ABB2BF;"> attempt </span><span style="color:#C678DD;">in</span><span style="color:#56B6C2;"> range</span><span style="color:#ABB2BF;">(max_retries </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">        try</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#61AFEF;">            process_document_change</span><span style="color:#ABB2BF;">(event)</span></span>
<span class="line"><span style="color:#C678DD;">            return</span><span style="color:#7F848E;font-style:italic;">  # 成功，直接返回</span></span>
<span class="line"><span style="color:#C678DD;">        except</span><span style="color:#ABB2BF;"> TransientError </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> e:</span></span>
<span class="line"><span style="color:#C678DD;">            if</span><span style="color:#ABB2BF;"> attempt </span><span style="color:#56B6C2;">==</span><span style="color:#ABB2BF;"> max_retries:</span></span>
<span class="line"><span style="color:#C678DD;">                break</span></span>
<span class="line"><span style="color:#ABB2BF;">            wait_time </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 2</span><span style="color:#56B6C2;"> **</span><span style="color:#ABB2BF;"> (attempt </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">)  </span><span style="color:#7F848E;font-style:italic;"># 指数退避：2s, 4s, 8s</span></span>
<span class="line"><span style="color:#ABB2BF;">            logger.</span><span style="color:#61AFEF;">warning</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Attempt </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">attempt </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 1}</span><span style="color:#98C379;"> failed: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">e</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">, retrying in </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">wait_time</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">s&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">            time.</span><span style="color:#61AFEF;">sleep</span><span style="color:#ABB2BF;">(wait_time)</span></span>
<span class="line"><span style="color:#C678DD;">        except</span><span style="color:#ABB2BF;"> PermanentError </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> e:</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">            # 永久性错误（如格式错误），不重试，直接打入死信队列</span></span>
<span class="line"><span style="color:#ABB2BF;">            logger.</span><span style="color:#61AFEF;">error</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Permanent error, sending to DLQ: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">e</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">            dlq.</span><span style="color:#61AFEF;">send</span><span style="color:#ABB2BF;">(event, </span><span style="color:#E06C75;font-style:italic;">reason</span><span style="color:#56B6C2;">=str</span><span style="color:#ABB2BF;">(e))</span></span>
<span class="line"><span style="color:#C678DD;">            return</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 超过最大重试次数，打入死信队列并告警</span></span>
<span class="line"><span style="color:#ABB2BF;">    logger.</span><span style="color:#61AFEF;">error</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Max retries exceeded for </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">event[</span><span style="color:#98C379;">&#39;doc_id&#39;</span><span style="color:#ABB2BF;">]</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    dlq.</span><span style="color:#61AFEF;">send</span><span style="color:#ABB2BF;">(event, </span><span style="color:#E06C75;font-style:italic;">reason</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;max_retries_exceeded&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    alert.</span><span style="color:#61AFEF;">trigger</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;Document update failed after </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">max_retries</span><span style="color:#D19A66;">}</span><span style="color:#98C379;"> retries: </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">event[</span><span style="color:#98C379;">&#39;doc_id&#39;</span><span style="color:#ABB2BF;">]</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>错误分类很重要。网络超时、API 限流这类瞬时错误可以重试；格式错误、字段缺失这类永久错误不应该反复重试，重试多少次都不会成功，只会浪费资源。</p><p>死信队列里的消息不能一直堆着。建议定期 Review，比如每周看一次，修复原因后再重新投递。</p><h3 id="回滚机制-出问题时的应急通道" tabindex="-1"><a class="header-anchor" href="#回滚机制-出问题时的应急通道"><span>回滚机制：出问题时的应急通道</span></a></h3><p>回滚不是后悔药，而是应急通道。好的回滚机制应该让操作者能快速切回上一个健康状态。</p><p>索引别名切换的回滚最简单。别名切换后，如果新索引有问题，把别名指回旧索引即可。前提是旧索引还没删。</p><p>模型升级的回滚，要在升级前记录旧模型的 <code>model_name</code>、<code>model_version</code> 和对应索引。如果新模型表现异常，优先把模型与索引一起切回旧版本；旧索引已经清理时，才需要基于旧模型重建。</p><p>数据版本回滚可以利用 <code>updated_at</code> 和 <code>version_id</code> 字段。需要回滚到某个时间点时，从历史快照恢复。快照可以是向量库 snapshot，也可以放在独立对象存储里。</p><p>权限回滚要更谨慎。如果权限变更导致数据泄露，第一步不是慢慢修索引，而是立刻阻断影响范围：下线相关知识库或租户检索入口、禁用问题索引、强制引用前鉴权。只有无法界定影响面时，才考虑全局停服。</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> rollback_to_version</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">target_version_id</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 查询目标版本的快照</span></span>
<span class="line"><span style="color:#ABB2BF;">    snapshot </span><span style="color:#56B6C2;">=</span><span style="color:#61AFEF;"> get_snapshot</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">version_id</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">target_version_id)</span></span>
<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#C678DD;"> not</span><span style="color:#ABB2BF;"> snapshot:</span></span>
<span class="line"><span style="color:#C678DD;">        raise</span><span style="color:#ABB2BF;"> ValueError(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;No snapshot found for version </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">target_version_id</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 停止服务</span></span>
<span class="line"><span style="color:#ABB2BF;">    service.</span><span style="color:#61AFEF;">set_status</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;maintenance&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 恢复快照</span></span>
<span class="line"><span style="color:#ABB2BF;">    vector_db.</span><span style="color:#61AFEF;">restore</span><span style="color:#ABB2BF;">(snapshot)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 重启服务</span></span>
<span class="line"><span style="color:#ABB2BF;">    service.</span><span style="color:#61AFEF;">set_status</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;active&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 发送告警</span></span>
<span class="line"><span style="color:#ABB2BF;">    alert.</span><span style="color:#61AFEF;">trigger</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">f</span><span style="color:#98C379;">&quot;System rolled back to version </span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">target_version_id</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="灰度发布-新策略先小流量验证" tabindex="-1"><a class="header-anchor" href="#灰度发布-新策略先小流量验证"><span>灰度发布：新策略先小流量验证</span></a></h3><p>知识库更新策略也要像 APP 发布一样灰度，不要一把梭。</p><p>常见灰度方式有几种：按文档数量灰度，比如先更新 10% 文档；按用户灰度，比如先让 5% 用户看到新索引结果；按问题类型灰度，比如先验证精确查询这类对索引变化更敏感的问题。</p><p>灰度期间要重点盯这些指标。下面的阈值只是示例，生产环境要基于历史基线、离线评估集和线上 A/B 结果校准，不能直接照抄。</p><table><thead><tr><th>指标</th><th>含义</th><th>告警阈值</th></tr></thead><tbody><tr><td><code>retrieval_hit_rate@10</code></td><td>前 10 个召回结果中包含正确答案的比例</td><td>下降 &gt; 5%</td></tr><tr><td><code>avg_answer_latency</code></td><td>平均回答延迟</td><td>上升 &gt; 20%</td></tr><tr><td><code>citation_accuracy</code></td><td>引用准确性</td><td>下降 &gt; 3%</td></tr><tr><td><code>user_feedback_negative_rate</code></td><td>用户负面反馈率</td><td>上升 &gt; 2%</td></tr></tbody></table><p>任何一个关键指标触发告警，都应该暂停灰度，先排查问题。别等全量上线后才发现召回质量掉了。</p><h2 id="知识库更新有哪些常见坑" tabindex="-1"><a class="header-anchor" href="#知识库更新有哪些常见坑"><span>知识库更新有哪些常见坑？</span></a></h2><h3 id="坑一-只插入新向量-不删除旧向量" tabindex="-1"><a class="header-anchor" href="#坑一-只插入新向量-不删除旧向量"><span>坑一：只插入新向量，不删除旧向量</span></a></h3><p>这是最常见的问题。文档被修改 5 次，向量库里留下 5 个版本。用户查询时召回旧版本，模型基于过时信息回答。</p><p>解决思路很简单，但必须做：修改文档时同步处理旧向量。可以在写入新向量前，先根据 <code>doc_id</code> 清理旧记录。</p><h3 id="坑二-embedding-模型混用" tabindex="-1"><a class="header-anchor" href="#坑二-embedding-模型混用"><span>坑二：Embedding 模型混用</span></a></h3><p>索引用模型 A，查询用模型 B，向量空间完全不兼容。</p><p>解决方式是把 <code>embedding_model</code> 和 <code>embedding_model_version</code> 作为必填元数据。查询前校验模型版本，不匹配就拒绝或降级。</p><h3 id="坑三-chunk-策略变了-但历史数据不重建" tabindex="-1"><a class="header-anchor" href="#坑三-chunk-策略变了-但历史数据不重建"><span>坑三：Chunk 策略变了，但历史数据不重建</span></a></h3><p>从固定长度切分改成语义切分，从 500 Token 改成 800 Token，只对新文档生效，历史数据还是旧策略。这会导致一个知识库里混着多套切分逻辑，召回评估也会变得很乱。</p><p>解决方式是给 Chunk 策略加版本。可以全量重建，也可以先写入新版索引并逐批迁移旧文档，验证后再切换活动版本；不能让两套策略在没有版本标记的情况下混用。</p><h3 id="坑四-文档删除后仍被召回" tabindex="-1"><a class="header-anchor" href="#坑四-文档删除后仍被召回"><span>坑四：文档删除后仍被召回</span></a></h3><p>软删除没做好，或者删除逻辑只处理了向量库，没处理全文索引。</p><p>删除操作必须三端一致：向量库、元数据库、全文索引都要同步处理。更稳的做法是用 outbox pattern 记录变更事件，消费者幂等执行；再通过定期 reconciliation 对比源系统、元数据库、向量库、全文索引，修复漏删、漏写和乱序事件。</p><h3 id="坑五-权限元数据不同步" tabindex="-1"><a class="header-anchor" href="#坑五-权限元数据不同步"><span>坑五：权限元数据不同步</span></a></h3><p>文档权限从“公开”改成“仅管理员可见”，但向量库里的 <code>acl</code> 字段没更新。</p><p>权限变更必须触发文档重新索引。如果向量库支持原子更新 ACL 字段，可以只更新元数据而不重建向量，但前提是向量库有这个能力。</p><h3 id="坑六-变更检测漏检" tabindex="-1"><a class="header-anchor" href="#坑六-变更检测漏检"><span>坑六：变更检测漏检</span></a></h3><p>Webhook 漏发、CDC 延迟、轮询间隔太大，都会导致文档已经变了，但索引没变。</p><p>解决方式是事件驱动 + 轮询兜底。同时建立数据新鲜度监控，定期检查源系统和向量库里的 <code>updated_at</code>。如果源系统时间比索引时间新超过阈值，就触发告警，必要时自动重新索引。</p><h2 id="如何保证知识库更新的可观测性" tabindex="-1"><a class="header-anchor" href="#如何保证知识库更新的可观测性"><span>如何保证知识库更新的可观测性？</span></a></h2><p>知识库更新链路必须有监控，否则就是盲跑。文档有没有更新、哪一步失败、失败后有没有补偿，不能靠用户投诉来发现。</p><p>关键监控指标可以从这些开始：</p><table><thead><tr><th>指标</th><th>说明</th><th>推荐告警阈值</th></tr></thead><tbody><tr><td><code>index_lag_seconds</code></td><td>从文档变更到索引完成的时间</td><td>&gt; 5 分钟</td></tr><tr><td><code>failed_updates_total</code></td><td>失败的更新操作累计数</td><td>&gt; 0 持续 10 分钟</td></tr><tr><td><code>dlq_size</code></td><td>死信队列当前积压量</td><td>&gt; 100</td></tr><tr><td><code>retrieval_hit_rate</code></td><td>召回准确率</td><td>环比下降 &gt; 5%</td></tr><tr><td><code>stale_docs_count</code></td><td>陈旧文档数量，源系统已更新但索引未更新</td><td>&gt; 10</td></tr><tr><td><code>source_to_queue_lag_seconds</code></td><td>源系统变更到事件入队延迟</td><td>&gt; 1 分钟</td></tr><tr><td><code>queue_to_index_lag_seconds</code></td><td>事件入队到索引完成延迟</td><td>&gt; 5 分钟</td></tr><tr><td><code>index_success_rate</code></td><td>索引成功率</td><td>&lt; 99%</td></tr><tr><td><code>partial_index_count</code></td><td>部分写入成功但未完成的文档数</td><td>&gt; 0 持续 30 分钟</td></tr><tr><td><code>acl_mismatch_count</code></td><td>源系统 ACL 与索引 ACL 不一致数量</td><td>&gt; 0</td></tr></tbody></table><p>每次更新操作都应该记录审计日志，包括 <code>doc_id</code>、<code>change_type</code>（新增 / 修改 / 删除）、<code>timestamp</code>、<code>operator</code>（自动 / 手动）、<code>result</code>（成功 / 失败）、<code>error_message</code>。真正出问题时，这些字段能帮你快速定位是哪条记录、哪个环节、什么时候失败的。</p><h2 id="上线检查" tabindex="-1"><a class="header-anchor" href="#上线检查"><span>上线检查</span></a></h2><p>上线前要验证四件事：</p><ol><li>索引和查询使用同一套 Embedding 模型及版本；</li><li>所有候选在进入模型上下文前完成鉴权；</li><li>文档更新通过活动版本或别名原子切换；向量库、元数据库、全文索引和缓存的失败能够被补偿任务发现。</li><li><code>doc_id</code>、<code>content_hash</code>、<code>version_id</code>、索引状态和审计日志应当贯穿这条链路。</li></ol><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>RAG 知识库更新不只是写一个定时任务重新索引。它涉及变更检测、数据一致性、幂等写入、版本控制、灰度发布、回滚机制和可观测性。</p><p>几个结论可以记住。</p><p>Embedding 模型一致性是硬规则。更换模型必须全量重建索引，不能偷懒。</p><p>元数据设计是增量更新的前提。<code>doc_id</code>、<code>content_hash</code>、<code>version_id</code>、<code>is_deleted</code> 这些字段，是幂等更新、版本追踪和回滚的基础。</p><p>删除操作必须三端一致。向量库、元数据库、全文索引都要同步处理，否则迟早会出现幽灵数据。</p><p>增量更新负责日常变化，全量重建负责周期性健康维护。两者配合起来，系统才不容易长期漂移。</p><p>索引别名切换是生产级灰度和回滚的常用做法。先建新索引，验证后切换，旧索引保留一段时间兜底。</p><p>幂等、重试、死信队列是更新链路可靠性的基本盘。可观测性则是最后一道防线：不知道更新有没有成功，就等于没更新。</p><p>RAG 知识库维护不是上线前做一次就结束，而是上线后才真正开始。</p><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://particula.tech/blog/update-rag-knowledge-without-rebuilding" target="_blank" rel="noopener noreferrer">How to Update RAG Knowledge Base Without Rebuilding Everything</a></li><li><a href="https://apxml.com/courses/optimizing-rag-for-production/chapter-7-rag-scalability-reliability-maintainability/rag-knowledge-base-updates" target="_blank" rel="noopener noreferrer">RAG Knowledge Base Management: Updates &amp; Refresh</a></li><li><a href="https://pub.towardsai.net/rag-in-practice-exploring-versioning-observability-and-evaluation-in-production-systems-85dc28e1d9a8" target="_blank" rel="noopener noreferrer">RAG in Practice: Versioning, Observability, and Evaluation in Production</a></li><li><a href="https://coralogix.com/ai-blog/rag-in-production-deployment-strategies-and-practical-considerations/" target="_blank" rel="noopener noreferrer">RAG in Production: Deployment Strategies &amp; Practical Considerations</a></li><li><a href="https://www.nb-data.com/p/23-rag-pitfalls-and-how-to-fix-them" target="_blank" rel="noopener noreferrer">23 RAG Pitfalls and How to Fix Them</a></li><li><a href="https://medium.com/@vasanthancomrads/incremental-indexing-strategies-for-large-rag-systems-e3e5a9e2ced7" target="_blank" rel="noopener noreferrer">Incremental Indexing Strategies for Large RAG Systems</a></li><li><a href="https://www.dbi-services.com/blog/rag-series-embedding-versioning-with-pgvector-why-event-driven-architecture-is-a-precondition-to-ai-data-workflows/" target="_blank" rel="noopener noreferrer">RAG Series: Embedding Versioning with pgvector</a></li></ul>`,75)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};